def solution(grid):
    rows = len(grid)
    columns = len(grid[0])
    settled = [[0] * columns for _ in range(rows)]
    for column in range(columns):
        write = rows - 1
        for row in range(rows - 1, -1, -1):
            if grid[row][column] != 0:
                settled[write][column] = grid[row][column]
                write -= 1
    return settled

def solution(values, size):
    rows = len(values)
    columns = len(values[0])
    prefix = [[0] * (columns + 1) for _ in range(rows + 1)]
    for row in range(rows):
        running = 0
        for column in range(columns):
            running += values[row][column]
            prefix[row + 1][column + 1] = prefix[row][column + 1] + running
    best = None
    for bottom in range(size, rows + 1):
        for right in range(size, columns + 1):
            total = prefix[bottom][right] - prefix[bottom - size][right] - prefix[bottom][right - size] + prefix[bottom - size][right - size]
            if best is None or total > best:
                best = total
    return best
